        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        background:
          radial-gradient(circle at top left, rgba(34, 87, 213, 0.16), transparent 32rem),
          linear-gradient(135deg, #f8fbff 0%, var(--background) 55%, #edf3ff 100%);
        color: var(--text);
