      .helper-text {
        color: var(--muted);
      }

      .error-text {
        color: var(--danger);
        font-weight: 700;
      }

      [hidden] {
        display: none;
      }

      button {
        width: 100%;
        border: 0;
        border-radius: 999px;
        background: var(--primary);
        color: #ffffff;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        margin-top: 1.25rem;
        padding: 0.95rem 1.25rem;
        transition:
          background-color 160ms ease,
          transform 160ms ease,
          box-shadow 160ms ease;
