        background: var(--primary-strong);
        box-shadow: 0 12px 26px rgba(34, 87, 213, 0.28);
        transform: translateY(-1px);
      }

      button:active {
        transform: translateY(0);
      }

      .status {
        color: #166534;
        font-weight: 700;
        margin-left: 0;
        text-align: center;
      }

      @media (prefers-reduced-motion: reduce) {
        *,
