          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        .card,
        .form-field,
        .eyebrow,
        button {
          border: 1px solid CanvasText;
        }

        button {
          color: ButtonText;
          background: ButtonFace;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main class="page" id="main-content">
      <section class="card" aria-labelledby="page-title">
        <p class="eyebrow">Account setup</p>
        <h1 id="page-title">Review and continue</h1>
        <p class="intro">
          Confirm that you accept the product terms before finishing setup.
        </p>

        <form id="consent-form" novalidate>
          <p class="required-note" aria-hidden="true">* Required</p>

          <div class="form-field">
            <div class="checkbox-row">
              <input
                id="terms-consent"
                name="terms-consent"
                type="checkbox"
                required
                aria-describedby="terms-helper terms-error"
              >
              <label for="terms-consent">
                I agree to the <a href="/terms-of-use">Terms of Use</a>
                <span class="required-mark" aria-hidden="true">*</span>
              </label>
            </div>
            <p class="helper-text" id="terms-helper">
              Required to create and use your account.
            </p>
            <p class="error-text" id="terms-error" hidden>
              Error: You must agree to the Terms of Use to continue.
            </p>
          </div>

          <button type="submit">Continue</button>
          <p class="status" id="form-status" role="status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#consent-form");
      const consent = document.querySelector("#terms-consent");
      const error = document.querySelector("#terms-error");
      const status = document.querySelector("#form-status");

      function showConsentError() {
        consent.setAttribute("aria-invalid", "true");
        error.hidden = false;
        status.textContent = "";
        consent.focus();
      }

      function clearConsentError() {
        consent.removeAttribute("aria-invalid");
        error.hidden = true;
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!consent.checked) {
          showConsentError();
          return;
        }

        clearConsentError();
        status.textContent = "Thanks. Your consent has been submitted.";
      });

      consent.addEventListener("change", () => {
        if (consent.checked) {
          clearConsentError();
        }
      });
    </script>
  </body>
</html>
