const fs = require('fs');
const { chromium } = require('playwright');
const axe = require('axe-core');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });

  const initial = await page.evaluate(async () => await window.axe.run());
  await page.click('button[type="submit"]');
  const invalid = await page.evaluate(async () => await window.axe.run());
  const focused = await page.evaluate(() => document.activeElement && document.activeElement.id);

  await browser.close();

  const summarize = (result) => {
    const wcag = result.violations.filter((v) => !v.tags.includes('best-practice'));
    const bp = result.violations.filter((v) => v.tags.includes('best-practice'));
    return {
      wcag: wcag.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
      bp: bp.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) }))
    };
  };

  const output = { initial: summarize(initial), invalid: summarize(invalid), focusedAfterInvalidSubmit: focused };
  console.log(JSON.stringify(output, null, 2));

  const failed = output.initial.wcag.length || output.invalid.wcag.length || focused !== 'terms-consent';
  process.exit(failed ? 1 : 0);
})();
